namespace ghidra.pcode.exec;

using static org.junit.Assert;



using org.junit;
using org.junit;

using generic.test;
using ghidra;
using ghidra.app.plugin.processors.sleigh;
using ghidra.app.plugin.processors.sleigh;
using ghidra.framework;
using ghidra.framework;

public class PcodeFrameTest : AbstractGTest {
	static readonly string SAMPLE_ADD = """
			r0 = r0 + r1;
			""";
	static readonly string SAMPLE_ADD2 = """
			r0 = r0 + r1 + r2;
			""";
	static readonly string SAMPLE_IF = """
			if (r0 == r1) goto <skip>;
			r2 = r2 + 1;
			<skip>
			""";
	static readonly string SAMPLE_LOOP = """
			<loop>
			r0 = r0 + 1;
			if (r0 == r1) goto <loop>;
			""";
	static readonly string SAMPLE_BRANCH = """
			goto 0x1234;
			""";
	static readonly string SAMPLE_LOAD = """
			r0 = *:8 r1;
			""";
	static readonly string SAMPLE_LANG_USEROP = """
			pcodeop_one(r0);
			""";
	static readonly string SAMPLE_LIB_USEROP = """
			__lib_userop(r0);
			""";

	static class MyLib : AnnotatedPcodeUseropLibrary<Void> {
		/* @PcodeUserop */
		void __lib_userop() {
		}
	}

	SleighLanguage language;
	MyLib library = new MyLib();

	/* @Before */
	public void setUp()
    {
		if (!Application.isInitialized()) {
			Application.initializeApplication(
				new GhidraTestApplicationLayout(new File(getTestDirectoryPath())),
				new ApplicationConfiguration());
		}
		language = SleighLanguageHelper.getMockBE64Language();
	}

	private PcodeProgram compile(string sample) {
		return SleighProgramCompiler.compileProgram(language, "test", sample, library);
	}

	private PcodeFrame frame(string sample) {
		PcodeProgram program = compile(sample);
		return new PcodeFrame(language, program.code, program.userops);
	}

	/* @Test */
	public void testProgramToStringAdd()
    {
		PcodeProgram program = compile(SAMPLE_ADD);
		assertEquals("""
				<PcodeProgram:
				  r0 = INT_ADD r0, r1
				>""",
			program.toString());
	}

	/* @Test */
	public void testProgramToStringAdd2()
    {
		PcodeProgram program = compile(SAMPLE_ADD2);
		assertEquals("""
				<PcodeProgram:
				  $U200:8 = INT_ADD r0, r1
				  r0 = INT_ADD $U200:8, r2
				>""",
			program.toString());
	}

	/* @Test */
	public void testProgramToStringIf()
    {
		PcodeProgram program = compile(SAMPLE_IF);
		assertEquals("""
				<PcodeProgram:
				  $U200:1 = INT_EQUAL r0, r1
				  CBRANCH <0>, $U200:1
				  r2 = INT_ADD r2, 1:8
				<0>
				>""",
			program.toString());
	}

	/* @Test */
	public void testProgramToStringLoop()
    {
		PcodeProgram program = compile(SAMPLE_LOOP);
		assertEquals("""
				<PcodeProgram:
				<0>
				  r0 = INT_ADD r0, 1:8
				  $U300:1 = INT_EQUAL r0, r1
				  CBRANCH <0>, $U300:1
				>""",
			program.toString());
	}

	/* @Test */
	public void testProgramToStringLoad()
    {
		PcodeProgram program = compile(SAMPLE_LOAD);
		assertEquals("""
				<PcodeProgram:
				  r0 = LOAD ram(r1)
				>""",
			program.toString());
	}

	/* @Test */
	public void testProgramToStringLangUserop()
    {
		PcodeProgram program = compile(SAMPLE_LANG_USEROP);
		assertEquals("""
				<PcodeProgram:
				  CALLOTHER "pcodeop_one", r0
				>""",
			program.toString());
	}

	/* @Test */
	public void testProgramToStringLibUserop()
    {
		PcodeProgram program = compile(SAMPLE_LIB_USEROP);
		assertEquals("""
				<PcodeProgram:
				  CALLOTHER "__lib_userop", r0
				>""",
			program.toString());
	}

	/* @Test */
	public void testFrameToStringAdd()
    {
		PcodeFrame frame = frame(SAMPLE_ADD);
		assertEquals("""
				<p-code frame: index=0 {
				 -> NO ADDRESS.0: r0 = INT_ADD r0, r1
				}>""",
			frame.toString());

		frame.advance();
		assertEquals("""
				<p-code frame: index=1 {
				    NO ADDRESS.0: r0 = INT_ADD r0, r1
				 *> fall-through
				}>""",
			frame.toString());
	}

	/* @Test */
	public void testFrameToStringIf()
    {
		PcodeFrame frame = frame(SAMPLE_IF);
		assertEquals("""
				<p-code frame: index=0 {
				 -> NO ADDRESS.0: $U200:1 = INT_EQUAL r0, r1
				    NO ADDRESS.1: CBRANCH <0>, $U200:1
				    NO ADDRESS.2: r2 = INT_ADD r2, 1:8
				  <0>
				}>""",
			frame.toString());

		frame.advance();
		frame.advance();
		frame.advance();
		assertEquals("""
				<p-code frame: index=3 {
				    NO ADDRESS.0: $U200:1 = INT_EQUAL r0, r1
				    NO ADDRESS.1: CBRANCH <0>, $U200:1
				    NO ADDRESS.2: r2 = INT_ADD r2, 1:8
				  <0>
				 *> fall-through
				}>""",
			frame.toString());
	}

	/* @Test */
	public void testFrameToStringLoop()
    {
		PcodeFrame frame = frame(SAMPLE_LOOP);
		assertEquals("""
				<p-code frame: index=0 {
				  <0>
				 -> NO ADDRESS.0: r0 = INT_ADD r0, 1:8
				    NO ADDRESS.1: $U300:1 = INT_EQUAL r0, r1
				    NO ADDRESS.2: CBRANCH <0>, $U300:1
				}>""",
			frame.toString());
	}

	/* @Test */
	public void testFrameToStringBranch()
    {
		PcodeFrame frame = frame(SAMPLE_BRANCH);
		assertEquals("""
				<p-code frame: index=0 {
				 -> NO ADDRESS.0: BRANCH *[NO ADDRESS]0x1234
				}>""",
			frame.toString());

		frame.advance();
		frame.finishAsBranch();
		assertEquals("""
				<p-code frame: index=-1 branched=0 {
				 *> NO ADDRESS.0: BRANCH *[NO ADDRESS]0x1234
				}>""",
			frame.toString());
	}

	/* @Test */
	public void testFrameToStringLangUserop()
    {
		PcodeFrame frame = frame(SAMPLE_LANG_USEROP);
		assertEquals("""
				<p-code frame: index=0 {
				 -> NO ADDRESS.0: CALLOTHER "pcodeop_one", r0
				}>""",
			frame.toString());
	}

	/* @Test */
	public void testFrameToStringLibUserop()
    {
		PcodeFrame frame = frame(SAMPLE_LIB_USEROP);
		assertEquals("""
				<p-code frame: index=0 {
				 -> NO ADDRESS.0: CALLOTHER "__lib_userop", r0
				}>""",
			frame.toString());
	}
}
